'use client'

import { type AnyFormApi, type FormValidateOrFn, useForm } from '@tanstack/react-form'
import { InfoIcon } from 'lucide-react'
import {
  Children,
  cloneElement,
  createContext,
  type FormEvent,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react'
import { cn } from '@/lib/utils'
import { ProButton } from '../base/button'
import { ProDrawer, ProModal } from '../overlay'
import {
  renderSchemaField,
  type SchemaFieldValue,
  type SchemaValueField,
  type SchemaValueType,
} from './schema-render'
import {
  getControlValue,
  getErrorMessages,
  type ProFieldValidators as InternalProFieldValidators,
  withRequiredFormValidator,
  withRequiredValidator,
} from './validators'

/** Validators supported by a ProForm field at each validation phase. */
export interface ProFieldValidators<TValue = unknown> extends InternalProFieldValidators<TValue> {}

type OverlayFormSubmitter =
  | ReactNode
  | ((context: { submitting: boolean; cancel: () => void | Promise<void> }) => ReactNode)

type FormValues = Record<string, unknown>

/** Imperative TanStack Form instance exposed by ProForm. */
export type ProFormInstance<TFieldValues extends FormValues = FormValues> = ReturnType<
  typeof useProForm<TFieldValues>
>

/** Form-level submit validator, including Standard Schema validators. */
export type ProFormValidator<TFieldValues extends FormValues = FormValues> =
  FormValidateOrFn<TFieldValues>

const ProFormContext = createContext<ProFormInstance | null>(null)
const ProFormRequiredFieldsContext = createContext<{
  fields: Map<string, number>
  hasFormValidator: boolean
} | null>(null)

function useRequiredFieldsRegistry(hasFormValidator: boolean) {
  const fields = useRef(new Map<string, number>())
  return useMemo(() => ({ fields: fields.current, hasFormValidator }), [hasFormValidator])
}

interface OverlayFormProps<TFieldValues extends FormValues = FormValues> {
  trigger?: ReactNode
  title: string
  description?: string
  children?: ReactNode
  schema?: ProSchemaFormItem[]
  formRef?: Ref<ProFormInstance<TFieldValues>>
  validator?: ProFormValidator<TFieldValues>
  defaultValues?: TFieldValues
  open?: boolean
  onOpenChange?: (open: boolean) => void
  onFinish?: (values: TFieldValues) => void | Promise<void>
  onFinishFailed?: (errors: unknown) => void
  onCancel?: () => void | Promise<void>
  submitter?: false | OverlayFormSubmitter
  className?: string
}

interface ProFormProps<TFieldValues extends FormValues = FormValues> {
  children?: ReactNode
  schema?: ProSchemaFormItem[]
  formRef?: Ref<ProFormInstance<TFieldValues>>
  validator?: ProFormValidator<TFieldValues>
  defaultValues?: TFieldValues
  onFinish?: (values: TFieldValues) => void | Promise<void>
  onFinishFailed?: (errors: unknown) => void
  onReset?: () => void | Promise<void>
  submitter?:
    | false
    | ReactNode
    | ((context: { submitting: boolean; reset: () => void | Promise<void> }) => ReactNode)
  className?: string
}

type ProSchemaFormValue = SchemaFieldValue

/** Field state supplied to schema item render functions. */
export interface ProSchemaValueField extends SchemaValueField {}

/** Declarative field definition accepted by schema-driven forms. */
export interface ProSchemaFormItem {
  name: string
  label?: ReactNode
  valueType?: SchemaValueType
  required?: boolean
  disabled?: boolean
  hidden?: boolean
  tooltip?: ReactNode
  description?: ReactNode
  extra?: ReactNode
  errors?: string[]
  initialValue?: ProSchemaFormValue
  validators?: ProFieldValidators<ProSchemaFormValue>
  fieldProps?: Record<string, unknown>
  formItemProps?: Omit<FormItemProps, 'children' | 'label' | 'required' | 'disabled'>
  render?: (field: ProSchemaValueField, item: ProSchemaFormItem) => ReactNode
}

/** Composable TanStack Form wrapper with schema and render-prop support. */
export function ProForm<TFieldValues extends FormValues = FormValues>({
  children,
  schema,
  formRef,
  validator,
  defaultValues,
  onFinish,
  onFinishFailed,
  onReset,
  submitter,
  className,
}: ProFormProps<TFieldValues>) {
  const requiredFields = useRequiredFieldsRegistry(!!validator)
  const form = useProForm({
    defaultValues,
    validator,
    requiredFields: requiredFields.fields,
    onFinish,
    onFinishFailed,
  })

  useImperativeHandle(formRef, () => form, [form])

  async function reset() {
    form.reset(defaultValues)
    await onReset?.()
  }

  return (
    <ProFormContext value={form as ProFormInstance}>
      <ProFormRequiredFieldsContext value={requiredFields}>
        <form onSubmit={submitForm(form)} className={className}>
          <div className="mb-4">
            {schema && <ProSchemaFields schema={schema} />}
            {children}
          </div>
          {submitter !== false && (
            <form.Subscribe selector={(state) => state.isSubmitting}>
              {(submitting) => (
                <div
                  data-slot="pro-form-actions"
                  className="flex flex-wrap items-center gap-2 pt-2"
                >
                  {renderFormSubmitter(submitter, submitting, reset)}
                </div>
              )}
            </form.Subscribe>
          )}
        </form>
      </ProFormRequiredFieldsContext>
    </ProFormContext>
  )
}

/** Schema-required convenience wrapper around ProForm. */
export function ProSchemaForm<TFieldValues extends FormValues = FormValues>({
  schema,
  defaultValues,
  children,
  ...props
}: Omit<ProFormProps<TFieldValues>, 'children' | 'schema'> & {
  schema: ProSchemaFormItem[]
  defaultValues?: TFieldValues
  children?: ReactNode
}) {
  return (
    <ProForm<TFieldValues> schema={schema} defaultValues={defaultValues} {...props}>
      {children}
    </ProForm>
  )
}

/** ProForm hosted inside a modal and reset after close or success. */
export function ModalForm<TFieldValues extends FormValues = FormValues>({
  trigger,
  title,
  description,
  children,
  schema,
  formRef,
  validator,
  defaultValues,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  onFinish,
  onFinishFailed,
  onCancel,
  submitter,
  className,
}: OverlayFormProps<TFieldValues>) {
  const { form, requiredFields, open, setOpen, handleSubmit, handleCancel } = useOverlayForm({
    formRef,
    validator,
    defaultValues,
    open: controlledOpen,
    onOpenChange: controlledOnOpenChange,
    onFinish,
    onFinishFailed,
    onCancel,
  })

  return (
    <ProModal
      trigger={trigger}
      title={title}
      description={description}
      open={open}
      onOpenChange={setOpen}
    >
      <ProFormContext value={form as ProFormInstance}>
        <ProFormRequiredFieldsContext value={requiredFields}>
          <form
            onSubmit={handleSubmit}
            className={cn('flex flex-1 flex-col overflow-hidden', className)}
          >
            <div className="flex-1 overflow-y-auto px-1 py-2">
              {schema && <ProSchemaFields schema={schema} />}
              {children}
            </div>
            {submitter !== false && (
              <OverlayFormFooter
                slot="modal-form-footer"
                form={form as ProFormInstance}
                submitter={submitter}
                cancel={handleCancel}
                className="flex-col-reverse pt-4 sm:flex-row sm:justify-end"
              />
            )}
          </form>
        </ProFormRequiredFieldsContext>
      </ProFormContext>
    </ProModal>
  )
}

/** ProForm hosted inside a directional drawer. */
export function DrawerForm<TFieldValues extends FormValues = FormValues>({
  trigger,
  title,
  description,
  children,
  schema,
  formRef,
  validator,
  defaultValues,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  onFinish,
  onFinishFailed,
  onCancel,
  submitter,
  className,
  side = 'right',
}: OverlayFormProps<TFieldValues> & { side?: 'top' | 'right' | 'bottom' | 'left' }) {
  const { form, requiredFields, open, setOpen, handleSubmit, handleCancel } = useOverlayForm({
    formRef,
    validator,
    defaultValues,
    open: controlledOpen,
    onOpenChange: controlledOnOpenChange,
    onFinish,
    onFinishFailed,
    onCancel,
  })

  return (
    <ProDrawer
      trigger={trigger}
      title={title}
      description={description}
      open={open}
      onOpenChange={setOpen}
      side={side}
    >
      <ProFormContext value={form as ProFormInstance}>
        <ProFormRequiredFieldsContext value={requiredFields}>
          <form
            onSubmit={handleSubmit}
            className={cn('flex flex-1 flex-col overflow-hidden', className)}
          >
            <div className="flex-1 overflow-y-auto px-4 py-2">
              {schema && <ProSchemaFields schema={schema} />}
              {children}
            </div>
            {submitter !== false && (
              <OverlayFormFooter
                slot="drawer-form-footer"
                form={form as ProFormInstance}
                submitter={submitter}
                cancel={handleCancel}
                className="mt-auto flex-col p-4"
              />
            )}
          </form>
        </ProFormRequiredFieldsContext>
      </ProFormContext>
    </ProDrawer>
  )
}

function useOverlayForm<TFieldValues extends FormValues = FormValues>({
  formRef,
  validator,
  defaultValues,
  open: controlledOpen,
  onOpenChange,
  onFinish,
  onFinishFailed,
  onCancel,
}: {
  formRef?: Ref<ProFormInstance<TFieldValues>>
  validator?: ProFormValidator<TFieldValues>
  defaultValues?: TFieldValues
  open?: boolean
  onOpenChange?: (open: boolean) => void
  onFinish?: (values: TFieldValues) => void | Promise<void>
  onFinishFailed?: (errors: unknown) => void
  onCancel?: () => void | Promise<void>
}) {
  const [internalOpen, setInternalOpen] = useState(false)
  const requiredFields = useRequiredFieldsRegistry(!!validator)
  const open = controlledOpen ?? internalOpen

  function setOpen(value: boolean) {
    if (controlledOpen === undefined) setInternalOpen(value)
    onOpenChange?.(value)
  }

  const form = useProForm({
    defaultValues,
    validator,
    requiredFields: requiredFields.fields,
    onFinish,
    onFinishFailed,
    onSuccess: () => {
      setOpen(false)
      form.reset(defaultValues)
    },
  })
  useImperativeHandle(formRef, () => form, [form])

  async function handleCancel() {
    setOpen(false)
    form.reset(defaultValues)
    await onCancel?.()
  }

  function handleOpenChange(value: boolean) {
    setOpen(value)
    if (!value) form.reset(defaultValues)
  }

  return {
    form,
    requiredFields,
    open,
    setOpen: handleOpenChange,
    handleSubmit: submitForm(form),
    handleCancel,
  }
}

function useProForm<TFieldValues extends FormValues>({
  defaultValues,
  validator,
  requiredFields,
  onFinish,
  onFinishFailed,
  onSuccess,
}: {
  defaultValues?: TFieldValues
  validator?: ProFormValidator<TFieldValues>
  requiredFields: Map<string, number>
  onFinish?: (values: TFieldValues) => void | Promise<void>
  onFinishFailed?: (errors: unknown) => void
  onSuccess?: () => void | Promise<void>
}) {
  return useForm({
    defaultValues: (defaultValues ?? {}) as TFieldValues,
    validators: validator
      ? ({
          onSubmit: withRequiredFormValidator(validator, () => requiredFields.keys()),
        } as never)
      : undefined,
    onSubmit: async ({ value }) => {
      try {
        await onFinish?.(value)
        await onSuccess?.()
      } catch (error) {
        onFinishFailed?.(error)
      }
    },
    onSubmitInvalid: ({ formApi }) => onFinishFailed?.(getFormValidationErrors(formApi)),
  })
}

function getFormValidationErrors(form: AnyFormApi) {
  return {
    form: form.state.errors,
    fields: Object.fromEntries(
      Object.entries(form.state.fieldMeta).flatMap(([name, metadata]) =>
        metadata?.errors.length ? [[name, metadata.errors]] : [],
      ),
    ),
  }
}

function submitForm(form: AnyFormApi) {
  return (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    event.stopPropagation()
    void form.handleSubmit()
  }
}

function OverlayFormFooter({
  slot,
  form,
  submitter,
  cancel,
  className,
}: {
  slot: string
  form: ProFormInstance
  submitter?: OverlayFormSubmitter
  cancel: () => void | Promise<void>
  className?: string
}) {
  return (
    <form.Subscribe selector={(state) => state.isSubmitting}>
      {(submitting) => (
        <div data-slot={slot} className={cn('flex shrink-0 gap-2', className)}>
          {renderOverlaySubmitter(submitter, submitting, cancel)}
        </div>
      )}
    </form.Subscribe>
  )
}

function renderFormSubmitter(
  submitter: ProFormProps['submitter'],
  submitting: boolean,
  reset: () => void | Promise<void>,
) {
  if (typeof submitter === 'function') return submitter({ submitting, reset })
  if (submitter !== undefined && submitter !== null && submitter !== false) return submitter
  return (
    <ProButton type="submit" loading={submitting}>
      {submitting ? 'Submitting...' : 'Submit'}
    </ProButton>
  )
}

function renderOverlaySubmitter(
  submitter: OverlayFormSubmitter | undefined,
  submitting: boolean,
  cancel: () => void | Promise<void>,
) {
  if (typeof submitter === 'function') return submitter({ submitting, cancel })
  if (submitter !== undefined && submitter !== null) return submitter
  return (
    <>
      <ProButton variant="outline" disabled={submitting} onClick={cancel}>
        Cancel
      </ProButton>
      <ProButton type="submit" loading={submitting}>
        {submitting ? 'Submitting...' : 'Submit'}
      </ProButton>
    </>
  )
}

interface FormItemProps {
  className?: string
  children?: ReactNode
  name?: string
  bind?: boolean
  validators?: ProFieldValidators
  label?: ReactNode
  required?: boolean
  disabled?: boolean
  htmlFor?: string
  description?: ReactNode
  tooltip?: ReactNode
  errors?: string[]
  extra?: ReactNode
}

/** Binds one child control to the nearest ProForm field context. */
export function FormItem({
  className,
  children,
  name,
  bind = true,
  validators,
  label,
  required,
  disabled,
  htmlFor,
  description,
  tooltip,
  errors = [],
  extra,
}: FormItemProps) {
  const form = useContext(ProFormContext)
  const requiredFields = useContext(ProFormRequiredFieldsContext)
  const shouldBind = bind && name && form && isValidElement(children)

  useEffect(() => {
    if (!required || !name || !requiredFields) return
    const count = requiredFields.fields.get(name) ?? 0
    requiredFields.fields.set(name, count + 1)
    return () => {
      const nextCount = (requiredFields.fields.get(name) ?? 1) - 1
      if (nextCount > 0) requiredFields.fields.set(name, nextCount)
      else requiredFields.fields.delete(name)
    }
  }, [name, required, requiredFields])

  if (!shouldBind) {
    return (
      <FormItemContent
        className={className}
        label={label}
        required={required}
        disabled={disabled}
        htmlFor={htmlFor}
        description={description}
        tooltip={tooltip}
        errors={errors}
        extra={extra}
      >
        {children}
      </FormItemContent>
    )
  }

  return (
    <form.Field
      name={name as never}
      validators={
        withRequiredValidator(required && !requiredFields?.hasFormValidator, validators) as never
      }
    >
      {(field) => {
        const isInvalid = field.state.meta.isTouched && !field.state.meta.isValid
        const hasErrors = errors.length > 0
        return (
          <FormItemContent
            className={className}
            label={label}
            required={required}
            disabled={disabled}
            htmlFor={htmlFor ?? name}
            description={description}
            tooltip={tooltip}
            errors={hasErrors ? errors : isInvalid ? getErrorMessages(field.state.meta.errors) : []}
            extra={extra}
          >
            {cloneElement(Children.only(children) as ReactElement<Record<string, unknown>>, {
              id: htmlFor ?? name,
              name: field.name,
              value: field.state.value,
              disabled: disabled || undefined,
              required: required || undefined,
              'aria-invalid': hasErrors || isInvalid,
              onBlur: field.handleBlur,
              onChange: (value: unknown) =>
                (field.handleChange as (nextValue: unknown) => void)(getControlValue(value)),
            })}
          </FormItemContent>
        )
      }}
    </form.Field>
  )
}

function FormItemContent({
  className,
  children,
  label,
  required,
  disabled,
  htmlFor,
  description,
  tooltip,
  errors = [],
  extra,
}: Omit<FormItemProps, 'name' | 'bind' | 'validators'>) {
  return (
    <div
      className={cn('flex flex-col gap-1.5', className)}
      data-invalid={errors.length > 0 || undefined}
      data-disabled={disabled || undefined}
    >
      {label != null && (
        <div className="flex items-center gap-1.5">
          <label
            htmlFor={htmlFor}
            className={cn(
              'flex items-center gap-2 text-sm leading-5 font-medium select-none',
              disabled && 'cursor-not-allowed opacity-50',
            )}
          >
            {label}
          </label>
          {(tooltip ?? description) != null && (
            <ProButton
              variant="ghost"
              size="icon-xs"
              tooltip={tooltip ?? description}
              className="cursor-help"
            >
              <InfoIcon />
            </ProButton>
          )}
          {required && (
            <span className="text-sm leading-5 text-destructive" aria-hidden="true">
              *
            </span>
          )}
        </div>
      )}
      {children}
      {errors.length > 0 && (
        <p className="text-xs text-destructive" role="alert">
          {errors.join(', ')}
        </p>
      )}
      {extra != null && <div className="text-xs text-muted-foreground">{extra}</div>}
    </div>
  )
}

function ProSchemaFields({ schema }: { schema: ProSchemaFormItem[] }) {
  const form = useContext(ProFormContext)
  const requiredFields = useContext(ProFormRequiredFieldsContext)
  if (!form) throw new Error('ProSchemaFields must be rendered inside ProForm.')

  return (
    <div className="flex flex-col gap-4">
      {schema.map((item) => {
        if (item.hidden) return null

        return (
          <form.Field
            key={String(item.name)}
            name={item.name as never}
            defaultValue={item.initialValue as never}
            validators={
              withRequiredValidator(
                item.required && !requiredFields?.hasFormValidator,
                item.validators,
              ) as never
            }
          >
            {(field) => {
              const validationErrors =
                field.state.meta.isTouched && !field.state.meta.isValid
                  ? getErrorMessages(field.state.meta.errors)
                  : []
              const fieldErrors = item.errors?.length ? item.errors : validationErrors
              const valueField: ProSchemaValueField = {
                name: field.name,
                value: field.state.value as ProSchemaFormValue,
                invalid: fieldErrors.length > 0,
                onChange: (value) =>
                  (field.handleChange as (nextValue: ProSchemaFormValue) => void)(value),
                onBlur: field.handleBlur,
              }
              return (
                <FormItem
                  name={item.name}
                  bind={false}
                  label={item.label}
                  required={item.required}
                  disabled={item.disabled}
                  htmlFor={String(item.name)}
                  description={item.description}
                  tooltip={item.tooltip}
                  errors={fieldErrors}
                  extra={item.extra}
                  {...item.formItemProps}
                >
                  {item.render
                    ? item.render(valueField, item)
                    : renderSchemaField(item, valueField)}
                </FormItem>
              )
            }}
          </form.Field>
        )
      })}
    </div>
  )
}

import { Checkbox, Switch } from '../base/fields/checkbox'
import { DatePicker, DateRangePicker } from '../base/fields/date-picker'
import { DateTimePicker, TimePicker } from '../base/fields/date-time-picker'
import { Input, Password, Slider, Textarea } from '../base/fields/input'
import { Radio, Rate, Segmented } from '../base/fields/radio'
import { Select } from '../base/fields/select'

/** Values supported by built-in schema fields. */
export type SchemaFieldValue =
  | string
  | number
  | boolean
  | Date
  | string[]
  | number[]
  | { from?: Date; to?: Date }
  | undefined
  | null

/** Internal schema field state used by built-in renderers. */
export interface SchemaValueField {
  name: string
  value: SchemaFieldValue
  invalid: boolean
  onChange: (value: SchemaFieldValue) => void
  onBlur: () => void
}

/** Built-in schema field renderer names. */
export type SchemaValueType =
  | 'text'
  | 'email'
  | 'password'
  | 'textarea'
  | 'select'
  | 'multiSelect'
  | 'checkbox'
  | 'radio'
  | 'switch'
  | 'date'
  | 'dateRange'
  | 'dateTime'
  | 'time'
  | 'slider'
  | 'rate'
  | 'segmented'

/** Renders the built-in control for one schema item. */
export function renderSchemaField(
  item: {
    name: string
    valueType?: SchemaValueType
    disabled?: boolean
    required?: boolean
    fieldProps?: Record<string, unknown>
  },
  field: SchemaValueField,
) {
  const fieldProps = item.fieldProps ?? {}
  const value = field.value
  const textValue = String(value ?? '')
  const dateValue = value instanceof Date ? value : undefined
  const stringValue = typeof value === 'string' ? value : undefined
  const numberValue = typeof value === 'number' ? value : undefined

  switch (item.valueType ?? 'text') {
    case 'password':
      return (
        <Password
          {...fieldProps}
          id={item.name}
          value={textValue}
          disabled={item.disabled}
          required={item.required}
          aria-invalid={field.invalid}
          onChange={(event) => field.onChange(event.target.value)}
          onBlur={field.onBlur}
        />
      )
    case 'textarea':
      return (
        <Textarea
          {...fieldProps}
          id={item.name}
          value={textValue}
          disabled={item.disabled}
          required={item.required}
          aria-invalid={field.invalid}
          onChange={(event) => field.onChange(event.target.value)}
          onBlur={field.onBlur}
        />
      )
    case 'select':
    case 'multiSelect':
      return (
        <Select
          value={value as string | string[] | undefined}
          disabled={item.disabled}
          required={item.required}
          aria-invalid={field.invalid}
          multiple={item.valueType === 'multiSelect'}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'checkbox':
      return (
        <Checkbox
          value={value as boolean | string[] | undefined}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'radio':
      return (
        <Radio
          name={item.name}
          value={stringValue}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          required={item.required}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'switch':
      return (
        <Switch
          value={Boolean(field.value)}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'date':
      return (
        <DatePicker
          value={dateValue}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'dateRange':
      return (
        <DateRangePicker
          value={value as { from?: Date; to?: Date } | undefined}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'dateTime':
      return (
        <DateTimePicker
          value={dateValue}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'time':
      return (
        <TimePicker
          value={stringValue}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'slider':
      return (
        <Slider
          value={numberValue}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'rate':
      return (
        <Rate
          value={numberValue ?? 0}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
    case 'segmented':
      return (
        <Segmented
          value={stringValue}
          disabled={item.disabled}
          aria-invalid={field.invalid}
          onChange={field.onChange}
          onBlur={field.onBlur}
          {...fieldProps}
        />
      )
  }

  return (
    <Input
      {...fieldProps}
      id={item.name}
      type={item.valueType === 'email' ? 'email' : 'text'}
      value={textValue}
      disabled={item.disabled}
      required={item.required}
      aria-invalid={field.invalid}
      onChange={(event) => field.onChange(event.target.value)}
      onBlur={field.onBlur}
    />
  )
}

import type {
  FormValidateOrFn,
  StandardSchemaV1,
  StandardSchemaV1Issue,
} from '@tanstack/react-form'

type ProFieldValidator<TValue = unknown> =
  | ((props: { value: TValue }) => unknown)
  | StandardSchemaV1<TValue, unknown>

/** Validators supported by a ProForm field at each validation phase. */
export interface ProFieldValidators<TValue = unknown> {
  onChange?: ProFieldValidator<TValue>
  onBlur?: ProFieldValidator<TValue>
  onSubmit?: ProFieldValidator<TValue>
}

/** Composes required validation with an existing field validator. */
export function withRequiredValidator<TValue>(
  required?: boolean,
  validators?: ProFieldValidators<TValue>,
) {
  if (!required) return validators
  const validator = validators?.onSubmit
  return {
    ...validators,
    onSubmit: combineRequiredValidator(validator),
  }
}

/** Adds registered required fields to a form validator without replacing its own errors. */
export function withRequiredFormValidator<TValues extends Record<string, unknown>>(
  validator: FormValidateOrFn<TValues>,
  getRequiredFields: () => Iterable<string>,
): FormValidateOrFn<TValues> {
  if (isStandardSchema(validator)) {
    const standard = validator['~standard']
    return {
      '~standard': {
        ...standard,
        validate: (value: unknown) => {
          const result = standard.validate(value)
          if (result instanceof Promise) {
            return result.then((resolved) =>
              mergeStandardSchemaRequiredErrors(resolved, value, getRequiredFields()),
            )
          }
          return mergeStandardSchemaRequiredErrors(result, value, getRequiredFields())
        },
      },
    } satisfies StandardSchemaV1<TValues, unknown>
  }

  return (props) => {
    const result = validator(props)
    const fields = getRequiredFieldErrors(props.value, getRequiredFields())
    if (Object.keys(fields).length === 0) return result
    if (isGlobalFormError(result)) {
      return { ...result, fields: { ...fields, ...getDefinedErrors(result.fields) } }
    }
    return { form: result, fields }
  }
}

function combineRequiredValidator<TValue>(validator?: ProFieldValidator<TValue>) {
  if (!validator) return validateRequired
  if (typeof validator === 'function') {
    return (props: { value: TValue }) => validateRequired(props) ?? validator(props)
  }

  const standard = validator['~standard']
  return {
    '~standard': {
      ...standard,
      validate: async (value: unknown) => {
        const error = validateRequired({ value })
        if (error) return { issues: [{ message: error }] }
        return standard.validate(value as TValue)
      },
    },
  } satisfies StandardSchemaV1<TValue, unknown>
}

/** Returns the default required-field error for empty values. */
export function validateRequired({ value }: { value: unknown }) {
  if (value == null || value === '' || (Array.isArray(value) && value.length === 0)) {
    return 'This field is required.'
  }
  return undefined
}

function mergeStandardSchemaRequiredErrors(
  result: { value: unknown; issues?: undefined } | { issues: readonly StandardSchemaV1Issue[] },
  value: unknown,
  requiredFields: Iterable<string>,
) {
  const issues = 'issues' in result && result.issues ? [...result.issues] : []
  const issueFields = new Set(issues.map(getIssueField).filter(Boolean))

  for (const [name, message] of Object.entries(getRequiredFieldErrors(value, requiredFields))) {
    if (!issueFields.has(name)) issues.push({ message, path: name.split('.') })
  }

  return issues.length > 0 ? { issues } : result
}

function getRequiredFieldErrors(value: unknown, requiredFields: Iterable<string>) {
  const errors: Record<string, string> = {}
  for (const name of requiredFields) {
    const error = validateRequired({ value: getValueAtPath(value, name) })
    if (error) errors[name] = error
  }
  return errors
}

function getValueAtPath(value: unknown, path: string) {
  return (path.match(/[^.[\]]+/g) ?? []).reduce<unknown>((current, key) => {
    if (current == null || typeof current !== 'object') return undefined
    return (current as Record<string, unknown>)[key]
  }, value)
}

function getIssueField(issue: StandardSchemaV1Issue) {
  return issue.path
    ?.map((segment) =>
      typeof segment === 'object' && segment !== null && 'key' in segment
        ? String(segment.key)
        : String(segment),
    )
    .join('.')
}

function isStandardSchema<TValues extends Record<string, unknown>>(
  validator: FormValidateOrFn<TValues>,
): validator is StandardSchemaV1<TValues, unknown> {
  return typeof validator === 'object' && validator !== null && '~standard' in validator
}

function isGlobalFormError(
  value: unknown,
): value is { form?: unknown; fields: Record<string, unknown> } {
  return typeof value === 'object' && value !== null && 'fields' in value
}

function getDefinedErrors(fields: Record<string, unknown>) {
  return Object.fromEntries(Object.entries(fields).filter(([, error]) => error !== undefined))
}

/** Normalizes TanStack and Standard Schema errors for rendering. */
export function getErrorMessages(errors: unknown[]) {
  return errors.map((error) => {
    if (typeof error === 'string') return error
    if (error && typeof error === 'object' && 'message' in error) return String(error.message)
    return String(error)
  })
}

/** Extracts a value from native change events or returns direct field values. */
export function getControlValue(value: unknown) {
  if (value && typeof value === 'object' && 'target' in value) {
    const target = (
      value as {
        target: { type?: string; value: unknown; checked?: boolean }
      }
    ).target
    return target.type === 'checkbox' ? target.checked : target.value
  }
  return value
}
